+// The audit trail: one entry per request that may change data. Entries are
+// only appended, never edited or deleted.
+
+/** Appends an audit entry (time `at`, key name, method, path, status) and returns it. */
+export function recordAudit(store, { at, name, method, path, status }) {
+  const entry = { id: store.nextId("audit"), at, name, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** All audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
