+// API keys and roles. Pure rules: the HTTP layer passes in what it read from
+// the request.
+import { AppError } from "../errors.js";
+
+const RANK = { viewer: 1, cook: 2, manager: 3 };
+
+/** The key record for an `Authorization: Bearer <key>` header value; throws `unauthorized` if missing or unknown. */
+export function authenticate(store, header) {
+  const m = /^Bearer\s+(\S+)$/i.exec(String(header ?? "").trim());
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** The lowest role a request needs: `access` if the route names one, else viewer for GET and manager for the rest. */
+export function requiredRole(method, access = null) {
+  return access ?? (method === "GET" ? "viewer" : "manager");
+}
+
+/** Throws `forbidden` unless the key's role is at least `required`. */
+export function authorize(key, required) {
+  if ((RANK[key.role] ?? 0) < RANK[required]) throw new AppError("forbidden", { role: key.role });
+}
