@@ -0,0 +1,43 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, as } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw, store } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(bad.status, 401);
+  assert.equal(store.data.audit.length, 0);
+});
+
+test("viewers read, cooks cook, managers do the rest", async () => {
+  const { raw } = app();
+  const viewer = as(raw, "viewer");
+  const cook = as(raw, "cook");
+  assert.equal((await viewer({ path: "/items" })).status, 200);
+  const denied = await viewer({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(denied.status, 403);
+  assert.equal(denied.body.error.code, "forbidden");
+  assert.equal((await cook({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await cook({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await cook({ method: "POST", path: "/orders", body: {} })).status, 403);
+  assert.equal((await cook({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  assert.equal((await cook({ path: "/audit" })).status, 403);
+});
+
+test("changing requests are audited and GET /audit lists them newest first", async () => {
+  const { raw, store } = app();
+  await as(raw, "cook")({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await as(raw, "viewer")({ method: "POST", path: "/orders", body: {} });
+  await as(raw, "manager")({ path: "/items" });
+  const list = (await as(raw, "manager")({ path: "/audit" })).body;
+  assert.equal(list.length, 2);
+  assert.deepEqual(list.map((e) => [e.name, e.method, e.path, e.status]), [
+    ["viewer", "POST", "/orders", 403],
+    ["cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.match(list[0].at, /^2026-10-28T10:00:00/);
+  assert.equal(store.data.audit.length, 2);
+});
